<script setup>import{onMounted,reactive,ref,computed}from'vue';import{congeService}from'@/services/congeService';const soldes=ref([]),demandes=ref([]),msg=ref(''),err=ref(''),form=reactive({typeConge:'ANNUEL',dateDebut:'',dateFin:'',motif:''}),disponibleAujourdhui=computed(()=>soldes.value.filter(s=>s.annee<=new Date().getFullYear()).reduce((n,s)=>n+Number(s.disponible||0),0));const jours=computed(()=>{if(!form.dateDebut||!form.dateFin)return 0;let a=new Date(form.dateDebut),b=new Date(form.dateFin),n=0;for(;a<=b;a.setDate(a.getDate()+1))if(a.getDay()!==0&&a.getDay()!==6)n++;return n});async function load(){try{soldes.value=await congeService.solde();demandes.value=await congeService.mes()}catch(e){err.value=e.message||'Chargement impossible.'}}async function send(){try{await congeService.demander({...form,joursDemandes:jours.value});msg.value='Demande envoyée.';await load()}catch(e){err.value=e.message||'Demande invalide.'}}onMounted(load)</script>
<template><div class="container-fluid py-4"><h1 class="h3">Mes congés</h1><div class="alert alert-info">Solde annuel disponible à ce jour : <strong>{{disponibleAujourdhui}} jour(s)</strong></div><p v-if="msg" class="alert alert-success">{{msg}}</p><p v-if="err" class="alert alert-danger">{{err}}</p><form class="card card-body mb-4" @submit.prevent="send"><h2 class="h5">Nouvelle demande</h2><div class="row g-3"><div class="col-md-3"><label class="form-label">Type de congé</label><select v-model="form.typeConge" class="form-select"><option>ANNUEL</option><option>MALADIE</option><option>MATERNITE</option><option>SANS_SOLDE</option></select></div><div class="col-md-3"><label class="form-label">Date de début</label><input v-model="form.dateDebut" type="date" class="form-control" required></div><div class="col-md-3"><label class="form-label">Date de fin</label><input v-model="form.dateFin" type="date" class="form-control" required></div><div class="col-md-3"><label class="form-label">Jours ouvrés calculés</label><input :value="jours" class="form-control" readonly></div><div class="col-12"><label class="form-label">Motif</label><textarea v-model="form.motif" class="form-control" rows="3"></textarea></div></div><button class="btn btn-primary mt-3" :disabled="!jours">Envoyer la demande</button></form><section class="card card-body"><h2 class="h5">Mes demandes</h2><div v-for="d in demandes" :key="d.id" class="border-bottom py-2">{{d.typeConge}} · {{d.dateDebut}} → {{d.dateFin}} · {{d.joursDemandes}} jour(s) · <strong>{{d.statut}}</strong></div></section></div></template>
